DROP TABLE IF EXISTS family_members;

CREATE TABLE family_members (
  peck              integer PRIMARY KEY,
  name              text NOT NULL,
  nickname          text,
  gen               smallint,
  birth_date        date,
  marriage_date     date,
  divorced          boolean NOT NULL DEFAULT false,
  death_date        date,
  peck_date         date,
  parents           text,
  current_last_name text,
  step_notes        text,
  spouse_name       text,
  parent_peck       integer,
  spouse_peck       integer
);

-- Enable Row Level Security (public read)
ALTER TABLE family_members ENABLE ROW LEVEL SECURITY;
